chart.data:
{
	entries = monitorMemoryUsage();
	mb = 1024 * 1024;
	time = dateFormat('MM-dd HH:mm');
	config = {
		'type': 'line',
		'data': {
			'labels': $entries.map(e -> $time.format($e['date'])),
			'datasets': if($entries.isEmpty(), [], [
				{
					'label': #('Used'@en, 'Belegt'@de).localize(),
					'data': $entries.map(e -> $e['used'] / $mb),
					'pointRadius': 0,
					'order': 1
				},
				{
					'label': #('Reserved'@en, 'Reserviert'@de).localize(),
					'data': $entries.map(e -> $e['total'] / $mb),
					'pointRadius': 0,
					'order': 2
				},
				{
					'label': #('Maximum'@en, 'Maximal'@de).localize(),
					'data': $entries.map(e -> $e['max'] / $mb),
					'pointRadius': 0,
					'borderDash': [5, 5],
					'order': 3
				},
				{
					'type': 'bar',
					'label': #('Garbage collections'@en, 'Garbage Collections'@de).localize(),
					'data': count($entries.size()).map(i -> if($i == 0, 0, $entries[$i]['gcCount'] - $entries[$i - 1]['gcCount'])),
					'yAxisID': 'y1',
					'order': 4
				}
			])
		},
		'options': {
			'maintainAspectRatio': false,
			'animation': false,
			'interaction': { 'intersect': false, 'mode': 'index' },
			'scales': {
				'x': { 'ticks': { 'autoSkip': true, 'maxTicksLimit': 12, 'maxRotation': 0 } },
				'y': { 'beginAtZero': true, 'title': { 'display': true, 'text': #('Memory (MB)'@en, 'Speicher (MB)'@de).localize() } },
				'y1': { 'beginAtZero': true, 'position': 'right', 'grid': { 'drawOnChartArea': false }, 'ticks': { 'precision': 0 }, 'title': { 'display': true, 'text': #('Garbage collections'@en, 'Garbage Collections'@de).localize() } }
			}
		}
	};
	$config;
}
